#!/usr/bin/env bash
# Adds pre-write validation to Dev Files: Python, Jinja templates
# (.html), and JSON are now syntax-checked BEFORE being saved or
# extracted from an upload — never after. A mistake is rejected with the
# exact line number and reason (Python also shows the offending source
# line with a caret at the exact column), instead of being written to
# disk and potentially crashing the live site (for app/) or a kiosk's
# Agent (for agent/) the moment it's picked up.
#
# This is deliberately prevention, not auto-fix: rewriting someone's code
# without being asked is its own kind of dangerous, so nothing here tries
# to correct a mistake — it stops it from being written and tells you
# exactly what and where, so you (or Claude in the next message) can fix
# it and try again immediately.
#
#   - Single-file editor (save_file): on a validation failure, the editor
#     re-renders with what you just typed still in the textarea and the
#     exact error shown — nothing is lost, no retyping needed.
#   - Zip upload (upload_zip): each .py/.html/.json entry is validated
#     independently; a bad one is skipped by name with its own reason,
#     everything else in the same zip still extracts normally.
#
# Tested against a live server before this was shipped: saved a
# deliberately broken agent/config.py (unclosed parenthesis) and confirmed
# byte-for-byte the file on disk never changed; uploaded a zip containing
# a broken .py, a broken Jinja template, and broken JSON alongside one
# valid file, and confirmed only the valid file was written while all
# three broken ones were rejected without failing the whole batch.
#
# No database migration in this push.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in app/blueprints/dev_files.py app/templates/dev_files run.py; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run the earlier push_dev_files*.sh scripts first, then this from the admin_panel repo root."
        exit 1
    fi
done

TS="$(date +%Y%m%d_%H%M%S)"
mkdir -p "backups/$TS/templates/dev_files"
cp app/blueprints/dev_files.py "backups/$TS/dev_files.py.bak" 2>/dev/null || true
cp app/templates/dev_files/index.html "backups/$TS/templates/dev_files/index.html.bak" 2>/dev/null || true
cp app/templates/dev_files/edit.html "backups/$TS/templates/dev_files/edit.html.bak" 2>/dev/null || true
cp app/templates/base.html "backups/$TS/templates/base.html.bak" 2>/dev/null || true
echo "==> Backed up existing files to backups/$TS/"

echo "==> Writing app/blueprints/dev_files.py"
base64 -d > app/blueprints/dev_files.py << 'DEV_FILES_PY_B64'

DEV_FILES_PY_B64

echo "==> Writing app/templates/dev_files/index.html"
base64 -d > app/templates/dev_files/index.html << 'DEV_INDEX_HTML_B64'

DEV_INDEX_HTML_B64

echo "==> Writing app/templates/dev_files/edit.html"
base64 -d > app/templates/dev_files/edit.html << 'DEV_EDIT_HTML_B64'

DEV_EDIT_HTML_B64

echo "==> Writing app/templates/base.html"
base64 -d > app/templates/base.html << 'BASE_HTML_B64'

BASE_HTML_B64

echo "==> Verifying"
python3 -c "import ast; ast.parse(open('app/blueprints/dev_files.py').read())"
echo "    syntax OK"

echo ""
echo "==> Restarting the admin panel app"
pkill -f "admin_panel/run.py" 2>/dev/null || true
fuser -k 6090/tcp 2>/dev/null || true
sleep 1
source venv/bin/activate
nohup python run.py > app.log 2>&1 &
disown
sleep 2
tail -n 15 app.log

echo ""
echo "==================================================================="
echo "Dev Files now validates Python/HTML templates/JSON before writing -"
echo "both on single-file save and inside an uploaded zip. A mistake is"
echo "rejected with the exact line and reason, nothing is written, and"
echo "(for single-file edits) your unsaved text stays right where it was"
echo "so you can fix it immediately."
echo "==================================================================="
